corrected_code:
from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework import status
from invitations.models import Invitation
from organizations.models import OrganizationUser

@api_view(['POST'])
@permission_classes([IsAuthenticated])
def accept_workspace_invitation(request, key: str):
    try:
        invitation = Invitation.objects.get(key=key)
    except Invitation.DoesNotExist:
        return Response({'error': 'Invalid invitation key'}, status=status.HTTP_404_NOT_FOUND)

    if invitation.key_expired():
        return Response({'error': 'Invitation has expired'}, status=status.HTTP_400_BAD_REQUEST)

    # Verify that the authenticated user's email matches the intended invitee email address
    if request.user.email.lower() != invitation.email.lower():
        return Response(
            {'error': 'This invitation was issued to a different email address'},
            status=status.HTTP_403_FORBIDDEN
        )

    invitation.accepted = True
    invitation.save()

    OrganizationUser.objects.get_or_create(
        organization=invitation.inviter.organization,
        user=request.user
    )

    return Response({'status': 'joined', 'organization': invitation.inviter.organization.name})
